const ch = name => SESSION.channels.find(c => c.name === name);
const fmtT = s => { if (s == null) return "—"; const m = Math.floor(s/60); return `${m}:${(s%60).toFixed(1).padStart(4,"0")}`; };
const fmtT3 = s => { if (s == null) return "—"; const m = Math.floor(s/60); return `${m}:${(s%60).toFixed(3).padStart(6,"0")}`; };

function Label({ children, color = C.pink, style }) {
  return <div style={{ fontSize: 9, letterSpacing: 2.5, fontWeight: 700, color, ...style }}>{children}</div>;
}
function Card({ children, style }) {
  return <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 10, ...style }}>{children}</div>;
}
function BCLogo() {
  return <svg width="26" height="26" viewBox="0 0 30 30"><rect x="3" y="3" width="24" height="24" rx="5" fill="none" stroke={C.pink} strokeWidth="2"/><path d="M10 9L10 21 M10 9L17 9Q21 9 21 13Q21 15 18 15L10 15 M18 15Q22 15 22 19Q22 21 18 21L10 21" fill="none" stroke={C.silver3} strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round"/></svg>;
}

// ── Trace with optional lap markers + hover ───────────────────────
function Trace({ data, color, height = 60, step = false, laps = null, totalS = null, fill = false }) {
  const [hover, setHover] = useState(null);
  if (!data || !data.length) return null;
  const w = 600, h = height;
  const mn = Math.min(...data), mx = Math.max(...data);
  const range = mx - mn || 1;
  const x = i => (i / (data.length - 1)) * w;
  const y = v => h - ((v - mn) / range) * (h - 10) - 5;
  let d = "";
  data.forEach((v, i) => {
    if (i === 0) d += `M${x(i).toFixed(1)},${y(v).toFixed(1)}`;
    else if (step) d += `H${x(i).toFixed(1)}V${y(v).toFixed(1)}`;
    else d += `L${x(i).toFixed(1)},${y(v).toFixed(1)}`;
  });
  const fillPath = fill ? d + `L${w},${h}L0,${h}Z` : null;
  return (
    <div style={{ position: "relative" }}
      onMouseMove={e => {
        const r = e.currentTarget.getBoundingClientRect();
        const frac = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width));
        const idx = Math.round(frac * (data.length - 1));
        setHover({ frac, val: data[idx] });
      }}
      onMouseLeave={() => setHover(null)}>
      <svg viewBox={`0 0 ${w} ${h}`} style={{ width: "100%", height, display: "block" }} preserveAspectRatio="none">
        {laps && totalS && laps.filter(l => l.lap > 0).map(l => (
          <line key={l.lap} x1={(l.start_s/totalS)*w} y1="0" x2={(l.start_s/totalS)*w} y2={h} stroke={C.line} strokeWidth="1" strokeDasharray="3 3"/>
        ))}
        {fillPath && <path d={fillPath} fill={color} opacity="0.08"/>}
        <path d={d} fill="none" stroke={color} strokeWidth="1.5" strokeLinejoin="round"/>
        {hover && <line x1={hover.frac*w} y1="0" x2={hover.frac*w} y2={h} stroke={C.silver2} strokeWidth="0.75"/>}
      </svg>
      {hover && (
        <div style={{ position: "absolute", top: 2, left: `${Math.min(86, hover.frac*100)}%`, background: C.panel2, border: `1px solid ${C.line}`, borderRadius: 5, padding: "2px 7px", fontSize: 10, color: C.silver3, fontFamily: "monospace", pointerEvents: "none" }}>
          {hover.val.toFixed(1)}
        </div>
      )}
    </div>
  );
}

// ── Tire corner grid (temps / pressures) ──────────────────────────
function CornerGrid({ title, corners, unit, hot }) {
  return (
    <Card style={{ padding: "13px 15px" }}>
      <Label style={{ marginBottom: 10 }}>{title}</Label>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        {corners.map(c => {
          const pct = hot ? Math.min(1, Math.max(0, (c.max - hot[0]) / (hot[1] - hot[0]))) : 0;
          const col = pct > 0.75 ? C.risk : pct > 0.45 ? C.gold : C.good;
          return (
            <div key={c.k} style={{ background: C.panel2, border: `1px solid ${C.line}`, borderRadius: 8, padding: "9px 11px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: 1, color: C.dim }}>{c.k}</span>
                <span style={{ fontSize: 12, fontWeight: 700, color: col, fontFamily: "monospace" }}>{c.max.toFixed(0)}{unit}</span>
              </div>
              <div style={{ height: 3, background: C.line, borderRadius: 2, overflow: "hidden", marginBottom: 4 }}>
                <div style={{ width: `${pct*100}%`, height: "100%", background: col }}/>
              </div>
              <div style={{ fontSize: 9, color: C.dim, fontFamily: "monospace" }}>min {c.min.toFixed(0)}{unit}</div>
            </div>
          );
        })}
      </div>
    </Card>
  );
}

export default function App() {
  const [tab, setTab] = useState("OVERVIEW");
  const S = SESSION;
  const totalS = ch("Session Elapsed Time")?.max ?? 744;
  const speed = ch("Ground Speed"), rpm = ch("Engine RPM"), gear = ch("Gear");
  const thr = ch("Throttle Pos"), brk = ch("Brake Pos"), glat = ch("G Force Lat");
  const fuel = ch("Fuel Level"), steer = ch("Steering");
  const timedLaps = S.laps.filter(l => l.dur_s != null && l.lap > 0);
  const bestLap = timedLaps.reduce((a,b) => a.dur_s < b.dur_s ? a : b, timedLaps[0]);
  const fuelBurn = fuel ? (fuel.max - fuel.min) : 0;
  const fuelPerLap = timedLaps.length ? fuelBurn / (timedLaps.length + 0.5) : 0;

  const tyreT = ["FL","FR","RL","RR"].map(k => ({ k, min: ch(`Tyre Temp ${k} Centre`).min, max: ch(`Tyre Temp ${k} Centre`).max }));
  const brkT  = ["FL","FR","RL","RR"].map(k => ({ k, min: ch(`Brake Temp ${k}`).min, max: ch(`Brake Temp ${k}`).max }));
  const press = ["FL","FR","RL","RR"].map(k => ({ k, min: ch(`Tyre Pressure ${k}`).min, max: ch(`Tyre Pressure ${k}`).max }));

  const setupGroups = [
    { t: "AERO & BRAKES", keys: ["FW","RW","BrakeDuct","BrakeDuctRear","RearBrake","BrakePressure"] },
    { t: "DRIVETRAIN", keys: ["DiffPower","DiffCoast","DiffPreload","RearSplit","RevLimit","EngineMixture"] },
    { t: "FRONT AXLE", keys: ["FLCamber","FLPressure","FLSpring","FLRideHeight","FLCompound","FrontAntiSway","FrontToeIn"] },
    { t: "REAR AXLE", keys: ["RLCamber","RLPressure","RLSpring","RLRideHeight","RLCompound","RearToeIn"] },
  ];

  return (
    <div style={{ minHeight: "100vh", background: C.bg, fontFamily: "'DM Sans','Helvetica Neue',sans-serif", color: C.text }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,700;9..40,900&family=JetBrains+Mono:wght@400;700&display=swap');*{box-sizing:border-box;margin:0;padding:0}@keyframes fade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}.fade{animation:fade .3s ease forwards}::-webkit-scrollbar{width:5px;height:5px}::-webkit-scrollbar-thumb{background:#26262c;border-radius:3px}`}</style>

      {/* Header */}
      <div style={{ padding: "12px 22px", borderBottom: `1px solid ${C.line}`, display: "flex", alignItems: "center", gap: 12, background: C.panel }}>
        <BCLogo/>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 13, fontWeight: 900, letterSpacing: 1, color: C.silver3 }}>BYTECRAFT <span style={{ color: C.pink }}>RACING</span></div>
          <div style={{ fontSize: 9, color: C.dim }}>Session Dashboard</div>
        </div>
        <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: 1, color: C.good, border: `1px solid ${C.good}55`, borderRadius: 4, padding: "3px 9px" }}>INGEST COMPLETE</span>
      </div>

      {/* Session identity bar */}
      <div style={{ background: C.panel2, borderBottom: `1px solid ${C.line}`, padding: "13px 22px", display: "flex", alignItems: "center", gap: 22, flexWrap: "wrap" }}>
        <div>
          <div style={{ fontSize: 16, fontWeight: 900, color: C.silver3 }}>{S.header.venue}</div>
          <div style={{ fontSize: 10, color: C.dim, marginTop: 2 }}>Ferrari 488 GTE Evo · <span style={{ color: C.pink }}>GTE</span> WEC2023 · {S.header.driver} · {S.header.date} {S.header.time}</div>
        </div>
        <div style={{ marginLeft: "auto", display: "flex", gap: 20 }}>
          <div><div style={{ fontSize: 8, color: C.dim, letterSpacing: 1 }}>LAPS</div><div style={{ fontSize: 18, fontWeight: 900, color: C.silver3 }}>{S.ldx.totalLaps}</div></div>
          <div><div style={{ fontSize: 8, color: C.dim, letterSpacing: 1 }}>FASTEST</div><div style={{ fontSize: 18, fontWeight: 900, color: C.pink, fontFamily: "monospace" }}>{S.ldx.fastestTimeRaw}</div></div>
          <div><div style={{ fontSize: 8, color: C.dim, letterSpacing: 1 }}>TOP SPEED</div><div style={{ fontSize: 18, fontWeight: 900, color: C.silver3, fontFamily: "monospace" }}>{Math.round(speed.max)}<span style={{ fontSize: 10, color: C.dim }}> km/h</span></div></div>
          <div><div style={{ fontSize: 8, color: C.dim, letterSpacing: 1 }}>FUEL USED</div><div style={{ fontSize: 18, fontWeight: 900, color: C.gold, fontFamily: "monospace" }}>{fuelBurn.toFixed(1)}<span style={{ fontSize: 10, color: C.dim }}> L</span></div></div>
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display: "flex", gap: 4, padding: "0 22px", borderBottom: `1px solid ${C.line}` }}>
        {["OVERVIEW","LAPS","TIRES & BRAKES","SETUP"].map(t => (
          <div key={t} onClick={() => setTab(t)} style={{ cursor: "pointer", padding: "11px 14px", fontSize: 10.5, fontWeight: 700, letterSpacing: 1.2, color: tab === t ? C.pink : C.dim, borderBottom: `2px solid ${tab === t ? C.pink : "transparent"}` }}>{t}</div>
        ))}
      </div>

      <div style={{ maxWidth: 980, margin: "0 auto", padding: "22px 22px 60px" }}>

        {tab === "OVERVIEW" && (
          <div className="fade">
            <Label style={{ marginBottom: 10 }}>SESSION TRACE · DASHED LINES = LAP BOUNDARIES</Label>
            <Card style={{ padding: "12px 15px", marginBottom: 10 }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                <span style={{ fontSize: 10, fontWeight: 700, color: C.pink, letterSpacing: 1 }}>GROUND SPEED</span>
                <span style={{ fontSize: 10, color: C.dim, fontFamily: "monospace" }}>{speed.min.toFixed(0)} – {speed.max.toFixed(0)} km/h</span>
              </div>
              <Trace data={speed.trace} color={C.pink} height={72} laps={S.laps} totalS={totalS} fill/>
            </Card>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
              <Card style={{ padding: "12px 15px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                  <span style={{ fontSize: 10, fontWeight: 700, color: C.good, letterSpacing: 1 }}>THROTTLE</span>
                  <span style={{ fontSize: 10, color: C.dim, fontFamily: "monospace" }}>0 – 100 %</span>
                </div>
                <Trace data={thr.trace} color={C.good} height={52} laps={S.laps} totalS={totalS}/>
              </Card>
              <Card style={{ padding: "12px 15px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                  <span style={{ fontSize: 10, fontWeight: 700, color: C.risk, letterSpacing: 1 }}>BRAKE</span>
                  <span style={{ fontSize: 10, color: C.dim, fontFamily: "monospace" }}>{brk.min.toFixed(0)} – {brk.max.toFixed(0)} %</span>
                </div>
                <Trace data={brk.trace} color={C.risk} height={52} laps={S.laps} totalS={totalS}/>
              </Card>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 10 }}>
              <Card style={{ padding: "12px 15px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                  <span style={{ fontSize: 10, fontWeight: 700, color: C.blue, letterSpacing: 1 }}>ENGINE RPM</span>
                  <span style={{ fontSize: 10, color: C.dim, fontFamily: "monospace" }}>max {Math.round(rpm.max)}</span>
                </div>
                <Trace data={rpm.trace} color={C.blue} height={48}/>
              </Card>
              <Card style={{ padding: "12px 15px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                  <span style={{ fontSize: 10, fontWeight: 700, color: C.gold, letterSpacing: 1 }}>G LATERAL</span>
                  <span style={{ fontSize: 10, color: C.dim, fontFamily: "monospace" }}>{glat.min.toFixed(1)} … +{glat.max.toFixed(1)} G</span>
                </div>
                <Trace data={glat.trace} color={C.gold} height={48}/>
              </Card>
              <Card style={{ padding: "12px 15px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                  <span style={{ fontSize: 10, fontWeight: 700, color: C.orange, letterSpacing: 1 }}>FUEL LEVEL</span>
                  <span style={{ fontSize: 10, color: C.dim, fontFamily: "monospace" }}>{fuel.max.toFixed(0)} → {fuel.min.toFixed(1)} L</span>
                </div>
                <Trace data={fuel.trace} color={C.orange} height={48} fill/>
              </Card>
            </div>
            <Card style={{ padding: "12px 15px" }}>
              <div style={{ fontSize: 10, color: C.dim, lineHeight: 1.6 }}>
                <b style={{ color: C.silver2 }}>Session read:</b> {S.ldx.totalLaps} laps, fastest {S.ldx.fastestTimeRaw} on lap {S.ldx.fastestLap}.
                Fuel burn {fuelPerLap.toFixed(1)} L/lap projects ~{Math.floor(fuel.min / fuelPerLap)} laps remaining on current load.
                All values decoded from the raw MoTeC channels with the verified formula — no estimates.
              </div>
            </Card>
          </div>
        )}

        {tab === "LAPS" && (
          <div className="fade">
            <Label style={{ marginBottom: 10 }}>LAP BREAKDOWN · SEGMENTED FROM THE LAP NUMBER CHANNEL</Label>
            <Card style={{ overflow: "hidden", marginBottom: 14 }}>
              <div style={{ display: "grid", gridTemplateColumns: "70px 1fr 130px 130px", padding: "8px 15px", borderBottom: `1px solid ${C.line}`, fontSize: 8, color: C.dim, fontWeight: 700, letterSpacing: 1.5 }}>
                <span>LAP</span><span>TYPE</span><span style={{ textAlign: "right" }}>TIME</span><span style={{ textAlign: "right" }}>VS BEST</span>
              </div>
              {S.laps.map((l, i) => {
                const isBest = bestLap && l.lap === bestLap.lap && l.dur_s === bestLap.dur_s;
                const isOut = l.lap === 0;
                const isInc = l.dur_s == null;
                const delta = (!isOut && !isInc && bestLap) ? l.dur_s - bestLap.dur_s : null;
                return (
                  <div key={i} style={{ display: "grid", gridTemplateColumns: "70px 1fr 130px 130px", padding: "10px 15px", borderBottom: i < S.laps.length-1 ? `1px solid ${C.line}` : "none", alignItems: "center", background: isBest ? C.pinkBg : "transparent" }}>
                    <span style={{ fontSize: 13, fontWeight: 700, color: isBest ? C.pink : C.silver3, fontFamily: "monospace" }}>{l.lap}</span>
                    <span style={{ fontSize: 10, color: C.dim }}>
                      {isOut ? "Out lap (pit exit + first crossing)" : isInc ? "In progress at export" : isBest ? "Fastest lap ★" : "Flying lap"}
                    </span>
                    <span style={{ fontSize: 13, fontWeight: 700, color: isBest ? C.pink : isOut ? C.dim : C.silver3, fontFamily: "monospace", textAlign: "right" }}>{fmtT(l.dur_s)}</span>
                    <span style={{ fontSize: 11, color: delta == null ? C.dim : delta === 0 ? C.pink : C.gold, fontFamily: "monospace", textAlign: "right" }}>
                      {delta == null ? "—" : delta === 0 ? "BEST" : `+${delta.toFixed(1)}s`}
                    </span>
                  </div>
                );
              })}
            </Card>
            <Card style={{ padding: "12px 15px" }}>
              <div style={{ fontSize: 10, color: C.dim, lineHeight: 1.6 }}>
                Lap boundaries come from the .ld's own <b style={{ color: C.silver2 }}>Lap Number</b> channel (the .ldx stores only the summary).
                Cross-check: segmented lap {bestLap?.lap} measures {fmtT(bestLap?.dur_s)} vs the .ldx declared fastest {S.ldx.fastestTimeRaw} — the two independent sources agree.
              </div>
            </Card>
          </div>
        )}

        {tab === "TIRES & BRAKES" && (
          <div className="fade">
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 12 }}>
              <CornerGrid title="TYRE TEMP · CENTRE (°C)" corners={tyreT} unit="°" hot={[60, 120]}/>
              <CornerGrid title="BRAKE TEMP PEAK (°C)" corners={brkT} unit="°" hot={[400, 900]}/>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 12 }}>
              <CornerGrid title="TYRE PRESSURE COLD → HOT (kPa)" corners={press} unit="" hot={[165, 180]}/>
              <Card style={{ padding: "13px 15px" }}>
                <Label style={{ marginBottom: 10 }}>FRONT TYRE TEMP TRACE (°C)</Label>
                <div style={{ marginBottom: 8 }}>
                  <div style={{ fontSize: 9, color: C.dim, marginBottom: 3 }}>FL centre</div>
                  <Trace data={ch("Tyre Temp FL Centre").trace} color={C.gold} height={40}/>
                </div>
                <div>
                  <div style={{ fontSize: 9, color: C.dim, marginBottom: 3 }}>FR centre</div>
                  <Trace data={ch("Tyre Temp FR Centre").trace} color={C.orange} height={40}/>
                </div>
              </Card>
            </div>
            <Card style={{ padding: "12px 15px" }}>
              <div style={{ fontSize: 10, color: C.dim, lineHeight: 1.6 }}>
                <b style={{ color: C.silver2 }}>What the numbers say:</b> front tyres peak {tyreT[0].max.toFixed(0)}–{tyreT[1].max.toFixed(0)} °C vs rears {tyreT[2].max.toFixed(0)}–{tyreT[3].max.toFixed(0)} °C — a front-loaded car at COTA.
                Pressures grew {press[0].min.toFixed(0)} → {press[0].max.toFixed(0)} kPa cold-to-hot (setup cold: 140 kPa).
                Brakes peaked {Math.max(...brkT.map(b=>b.max)).toFixed(0)} °C front — healthy carbon range.
                This cold-to-hot delta is exactly the input the Tire Agent consumes in Phase 2.
              </div>
            </Card>
          </div>
        )}

        {tab === "SETUP" && (
          <div className="fade">
            <Label style={{ marginBottom: 10 }}>CAR SETUP · DECODED FROM .LDX <span style={{ color: C.dim, fontWeight: 400 }}>(cause side of the session)</span></Label>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
              {setupGroups.map(g => (
                <Card key={g.t} style={{ padding: "13px 15px" }}>
                  <Label style={{ marginBottom: 9 }}>{g.t}</Label>
                  {g.keys.map(k => S.setup[k] ? (
                    <div key={k} style={{ display: "flex", justifyContent: "space-between", padding: "5px 0", borderBottom: `1px solid ${C.line}` }}>
                      <span style={{ fontSize: 11, color: C.silver2 }}>{k}</span>
                      <span style={{ fontSize: 11, color: C.silver3, fontFamily: "monospace" }}>{S.setup[k]}</span>
                    </div>
                  ) : null)}
                </Card>
              ))}
            </div>
            <Card style={{ padding: "12px 15px", marginTop: 12 }}>
              <div style={{ fontSize: 10, color: C.dim, lineHeight: 1.6 }}>
                Front springs 220 N/mm vs rear 140, ride height 5.0 / 6.7 cm — consistent with the front-heavy tyre temps on the Tires tab.
                Telemetry is the effect; this setup is the cause. In Phase 2 the agents reason over both sides together.
              </div>
            </Card>
          </div>
        )}
      </div>
    </div>
  );
}
